def resolve(name): with factory() as session: events = SqlAlchemyWorkflowRuntimeRepository(session).list_events(queued.run_id, after_sequence=0, limit=100) assert any(event.kind == "nodeAttempt" and event.payload.get("status") == "started" for event in events) reads.append(name) return {"password": value}
worker = ProjectWorkflowWorkerManager(tmp_path / "temp", resolve_credential=resolve) dispatcher = _dispatcher(factory, worker, _NoBrowserResources()) try: await dispatcher.dispatch(queued.run_id, expected_status_revision=queued.status_revision, execution_generation=queued.execution_generation) async with asyncio.timeout(15): await dispatcher.wait_idle() with factory() as session: repository = SqlAlchemyWorkflowRuntimeRepository(session) run = repository.get_run(run_id=queued.run_id) events = repository.list_events(queued.run_id, after_sequence=0, limit=100) assert run.status == ("failed" if value == "" else "succeeded") assert reads == ["账号"] outputs = [event.payload["value"] for event in events if event.kind == "output"] # The shared runtime deliberately redacts credential-derived results. # Empty fields stay empty (invalid path); missing fields keep placeholders. > assert outputs == ([] if value == "" else [None]) E assert [] == [None] E E Right contains one more item: None E Use -v to get more diff
